-(void)deleteSms:(NSDictionary*)data ident:(id)ident {
    if(![data isKindOfClass:NSDictionary.class]){[self reply:ident result:nil error:Err(@"短信删除参数错误")];return;}
    NSString *direction=data[@"direction"],*index=data[@"index"],*key=data[@"key"],*phone=data[@"phone"];
    NSCharacterSet *digits=[NSCharacterSet decimalDigitCharacterSet];
    BOOL numeric=[index isKindOfClass:NSString.class]&&index.length>0&&index.length<=10&&[index rangeOfCharacterFromSet:digits.invertedSet].location==NSNotFound&&index.integerValue>0;
    if(![@[@"recv",@"send"]containsObject:direction]||!numeric||![key isKindOfClass:NSString.class]||!key.length||![phone isKindOfClass:NSString.class]){[self reply:ident result:nil error:Err(@"无法定位短信，先刷新再删除")];return;}
    [_queue addOperationWithBlock:^{
        NSError *error=nil;if(![self.router login:&error]){[self reply:ident result:nil error:error];return;}
        id raw=[self.router api:@"get_sms_data" data:nil nocheck:NO error:&error];if(error){[self reply:ident result:nil error:error];return;}
        NSArray *threads=[raw isKindOfClass:NSDictionary.class]?[raw allValues]:[raw isKindOfClass:NSArray.class]?raw:@[];BOOL found=NO;
        for(id item in threads){if(![item isKindOfClass:NSDictionary.class]||![[item[@"session_phone"]description]isEqual:phone])continue;
            for(NSString *field in item){if(![field hasPrefix:@"message_item_"])continue;id message=item[field];if(![message isKindOfClass:NSDictionary.class])continue;
                if([[message[@"rcvorsend"]description]isEqual:direction]&&[[message[@"childnode"]description]isEqual:index]&&[[message[@"key_index"]description]isEqual:key]){found=YES;break;}
            }if(found)break;
        }
        if(!found){[self reply:ident result:nil error:Err(@"短信记录已经变化，请刷新后重试")];return;}
        NSString *node=[direction isEqual:@"send"]?@"InternetGatewayDevice.X_FH_MobileNetwork.SMS_Send.SMS_SendMsg.":@"InternetGatewayDevice.X_FH_MobileNetwork.SMS_Recv.SMS_RecvMsg.";
        id response=[self.router api:@"del_xmlnode" data:@{@"url":node,@"index":index} nocheck:NO error:&error];
        if(error){[self reply:ident result:nil error:error];return;}
        if([response isKindOfClass:NSDictionary.class]&&response[@"success"]&&![@[@"true",@"1"]containsObject:[response[@"success"]description]]){[self reply:ident result:nil error:Err(@"CPE 未接受短信删除")];return;}
        [self reply:ident result:@{@"ok":@YES} error:nil];
    }];
}
-(void)saveMiFiConfig:(NSDictionary*)data ident:(id)ident {
    if(![data isKindOfClass:NSDictionary.class]){[self reply:ident result:nil error:Err(@"MiFi 设置参数不正确")];return;}
    NSString *address=MiFiNormalizeAddress(data[@"address"]);
    id password=data[@"password"];
    if(!address){[self reply:ident result:nil error:Err(@"请输入正确的 MiFi 局域网管理地址")];return;}
    NSDictionary *existing=MiFiReadConfig();
    if((![password isKindOfClass:NSString.class]||![password length])&&![existing[@"password"] length]){[self reply:ident result:nil error:Err(@"首次配置请填写 MiFi 管理密码")];return;}
    if(password&&![password isKindOfClass:NSString.class]){[self reply:ident result:nil error:Err(@"MiFi 密码格式不正确")];return;}
    [_miQueue addOperationWithBlock:^{
        NSDictionary *current=self.mifi.config?:MiFiReadConfig();
        NSString *retainedPassword=[password isKindOfClass:NSString.class]&&[password length]?password:(current[@"password"]?:@"");
        NSDictionary *updated=@{@"address":address,@"password":retainedPassword};
        BOOL changed=![current isEqualToDictionary:updated];
        if(!MiFiSaveConfig(updated)){[self reply:ident result:nil error:Err(@"MiFi 设置未能保存到本机钥匙串，请重试")];return;}
        if(changed){[self.mifi reset];self.mifi.config=updated;self.mifiAddress=address;self.mifiPassword=retainedPassword;}
        [self reply:ident result:@{@"saved":@YES,@"address":address,@"changed":@(changed),@"hasPassword":@(retainedPassword.length>0)} error:nil];
    }];
